(() => {
 'use strict';
 const A=window.LessonArticle,p=s=>`<p>${s}</p>`,f=s=>`<p class="element-formula">${s}</p>`,note=s=>`<p class="element-note">${s}</p>`;
 const card=(id,label=id)=>`<a href="bulk.html#${id}">${label}</a>`,lab=id=>`<figure data-contact-lab="${id}"></figure>`,legacy=i=>`<div data-contact-legacy="${i}"></div>`;
 const stat='https://documentation-be.hexagon.com/bundle/MSC_Nastran_2025.1_Linear_Static_Analysis_User_Guide/raw/resource/enus/MSC_Nastran_2025.1_Linear_Static_Analysis_User_Guide.pdf',qrg='https://documentation-be.hexagon.com/bundle/MSC_Nastran_2025.1_Quick_Reference_Guide/raw/resource/enus/MSC_Nastran_2025.1_Quick_Reference_Guide.pdf';
 const source=(url,t)=>`<a href="${url}" target="_blank" rel="noopener">${t} ↗</a>`;
 const sections=[
 ['meaning','支持・固着・摩擦接触は、伝えられる力が違う',legacy(0)+
 p('接触では、どの場所が押し合い、どこが離れ、どこが滑るかも解の一部です。初めからその面を固定すると、実物が離れる方向にも反力を伝えてしまいます。必要なのは複雑な設定を増やすことではなく、<strong>許す相対運動と伝える作用を先に決めること</strong>です。')+
 A.table(['理想化','法線方向','接線方向','使い分け'],[['SPCなどの支持','指定した変位を固定','選んだ成分を固定','既知の支持。必要なら引張の反力も伝える'],['永久固着・結合','開離しない','相対運動を拘束','接着破壊を扱わない結合や異なるメッシュの接続'],['摩擦なし接触','圧縮を伝え、開離を許す','接線力を伝えない','滑りを許す支持・摩擦を除いた比較'],['摩擦接触','圧縮と開離','固着または滑り','摩擦限界と荷重履歴を解く'],['凝着・接着破壊','引張も伝え、損傷で低下','接線方向も損傷則に従う','接着層や剥離を別の材料則で表す']])+
 p('接触体を剛体にしても、それだけで空間へ固定したことにはなりません。剛体の運動に対する支持・外力は別に指定します。'+ '<a href="theory.html#boundary">境界条件と拘束</a>との役割を分けて考えます。')],
 ['normal','開いているか、押し合っているか',
 p("台の上の部品を持ち上げるとすきまが開き、台が部品を押す力は消えます。逆に下ろすと、すきまが閉じてから初めて力が伝わります。")+
 legacy(1)+lab('normal')+
 f('g：表面間の開き（開く方向を正）\npn：圧縮接触圧を正\ng ≥ 0、pn ≥ 0、g pn = 0\n開離：g>0、pn=0\n接触：g=0、pn≥0')+
 p('この図でFを300 → 400 → 500 Nと変えます。300 Nではばねが0.3 mm縮み、台まで0.1 mm残ります。400 Nでは底面が台に届きますが、ばねだけで400 Nを支えられるので台の反力はまだ0です。500 Nで初めて台が差の100 Nを支えます。<strong>反力が0という値だけでは、離れているか、ちょうど触れたかは決まりません。</strong>すき間gを一緒に見ます。')+
 f('操作図：下向きu、ばねk、初期すき間g0\ng=g0−u、F=ku+R\nF≤kg0なら u=F/k、R=0\nF>kg0なら u=g0、R=F−kg0')+
 p('これを普通の支持で代用すると、荷重が反転しても台がブロックを引っ張る解が得られます。開く前後で剛性が切り替わるため、材料が弾性でも荷重の単純な重ね合わせは一般に成立しません。')],
 ['geometry','すき間は、節点の距離だけでは決まらない',
 p("厚さ2 mmの板を2枚、中央面間の距離を2 mmにして向かい合わせます。中央面は離れていますが、実物の表面はすでに触れています。")+
 lab('thickness')+
 f('向かい合うシェル、オフセット0、平行面の例\ng0=d−(t1+t2)/2\nd：中立面の距離、t1,t2：厚さ')+
 p('ソリッドの節点は通常は物理表面にありますが、シェルの節点は中立面などの基準面にあります。厚さ、法線、オフセットを含めて実表面を考えます。シェルの中立面を重ねると、実表面は厚さ分だけ干渉する場合があります。オフセットがあれば、その向きも加味します。')+
 p('初期干渉には、意図した締まりばめと、メッシュ・厚さ・位置の誤りがあります。「初期位置を無応力で調整する」設定は、応力を持つ締まりばめを解いたことにはなりません。物理的なすき間、接触探索の距離、許容貫通量を別々に記録します。')],
 ['penalty','接触剛性を大きくすれば、常に良くなるか',
 p("箱を床に載せた解析で、ごくわずかに箱が床に沈んでいます。その沈みに対してどれだけの力で押し返すかが接触剛性です。")+
 legacy(2)+lab('penalty')+
 f('貫通量 δ= max(0,−g)\nペナルティ近似：pn=kn δ（面積当たり）\n節点・集中ばねなら R=kc δ\n接触後：F=ku+kc(u−g0)\nu=(F+kc g0)/(k+kc)、δ=(F−kg0)/(k+kc)')+
 p('ペナルティ法は小さい貫通を許し、その量から押し返す力を計算します。表面のknは力/(面積×長さ)、集中ばねのkcは力/長さで、同じ数値を移せません。接触力の誤差を抑えるには部材の剛性に対して十分な接触剛性が必要ですが、過大な値は行列の尺度差や収束を悪化させます。')+
 p('貫通量を代表長さ・要素寸法・機能上許される変位と比較し、接触剛性を変えたときの反力・面圧・開離荷重の感度を見ます。許容貫通を小さくする設定と、探索範囲を狭くする設定は別です。')],
 ['methods','接触の状態を反復して決める',
 p('接触候補を閉じたと仮定して解くと、引張の接触反力が出る場所があります。その場所を開き、逆に貫通する場所を閉じて再びつり合いを解きます。接触状態と構造変形を互いに矛盾なく決めるため、反復が必要です。')+
 A.table(['方法の考え方','長所','注意'],[['ペナルティ','接触剛性として扱いやすい','有限の貫通と剛性選択の影響が残る'],['Lagrange乗数','接触の拘束力を追加未知量として扱う','未知量や連立方程式の性質が変わる'],['拡張Lagrange','乗数の更新とペナルティを組み合わせる','更新・収束条件が必要。無限剛性の一回計算ではない'],['アクティブ集合','開いている点と閉じている点を更新する','閉じた点のつり合いだけでなく、開いた点の貫通も調べる']])+
 p('名称の異なる接触方式を、同じ1つのばね式だけで説明しません。上の操作図はペナルティの原理を示す1自由度計算で、MSCの特定アルゴリズムを再現したものではありません。')],
 ['friction','固着中の摩擦力は、必要な分だけ生じる',
 p("机の上の箱を少しずつ強く横に押します。まだ滑らない間も、押す力に応じて摩擦力は変わっています。")+
 legacy(3)+lab('friction')+
 f('法線力N、接線力T、摩擦係数μ\n固着：|T|≤μN、理想的には相対滑り速度0\n滑り：|T|=μN、摩擦力は滑りの逆向き\n開離：N=0 → 摩擦力も0')+
 p('水平面を押さえて10 Nだけ横へ引き、摩擦限界が100 Nなら、必要な摩擦力は10 Nです。常に100 Nが発生するのではありません。力の条件と、滑っているかという運動の条件を同時に見ます。')+
 f('正則化したばね・滑り要素：u=ue+us、T=kt ue\n試行値 Ttrial=kt(u−us,old)\nT=clip(Ttrial,−μN,+μN)\nus,new=u−T/kt')+
 p('実際の数値モデルでは固着中にも小さい弾性的なずれを許す場合があります。それを累積滑りと同じ量として読みません。静摩擦と動摩擦、速度依存、せん断強度で上限を決めるモデルは別の則なので、μという名前だけで同一視しないようにします。')],
 ['history','除荷・逆向き載荷では、履歴が残る',lab('cycle')+
 p('滑った後に外力を減らすと、まず接線ばねの弾性ずれが戻ります。逆向きの上限に達してから逆滑りします。同じ変位でも履歴が違えば接線力が違うため、荷重順序を省略できません。')+
 f('摩擦の散逸増分 ΔD=μN |Δus| ≥ 0\n一定N、変位振幅A、Q=μN、A>Q/ktの定常往復\n1周期の散逸 Dcycle=4Q(A−Q/kt)\nA≤Q/ktで滑らなければ、この理想モデルの散逸は0')+
 p('摩擦による散逸を、材料損傷や塑性仕事と混同しません。接触減衰を追加した場合も、それは別のエネルギーです。摩擦で生まれる発熱を計算するには、熱への変換率、両面への分配、熱伝達を含む熱・構造の扱いが必要です。力学解析で摩擦係数を入れただけでは温度上昇は求まりません。')],
 ['partial','面全体の滑りと、一部の滑りを区別する',
 p("面を押し付けたまま横にずらすと、中央が動き出す前に、押し付けの弱い縁だけが滑る場合があります。")+
 lab('patches')+
 f('面上の局所条件：|t(x)|≤μ p(x)\n全体の接線力 T=∫A t dA、法線力 N=∫A p dA\n一方向に全面滑り、μ一定なら |T|=μN')+
 p('図を0.08 mmにすると、固着のままなら各区画に80 Nが必要です。両端は60 Nまでしか渡せず滑り、中央は上限180 Nのうち80 Nでまだ固着します。合計は60＋80＋60＝200 N。全体の上限300 Nに届く前に、端ではすでに滑りが起きています。')+
 p('メッシュを細かくした結果、接触域の面積や圧力分布が変わると、局所滑りも変わります。面全体の合力だけを一致させて検証を終えないようにします。')],
 ['surface','点対面・面対面と、接触側の選び方',
 p('接触探索では、一方の表面上の点が、相手のどの面に接するかを調べます。PRIMARY／SECNDRYや主面／従面という名称は探索側の役割です。MPCでの独立・従属自由度、あるいは空間に固定された面という意味と混同しません。')+
 A.table(['方式','考え方','確認'],[['Node-to-Segment','片側の節点と相手側の面を対応付ける','節点の粗密、面の滑らかさ、選択側による偏り'],['Segment-to-Segment','面の領域どうしの対応から作用を求める','積分・探索点、面の形状、メッシュの歪み'],['Small sliding','対応関係の変化が小さいとして扱う','相対移動が要素寸法に比べ十分小さいか'],['Finite / large sliding','移動に応じて相手面を更新する','面の乗り移り・回転・接触探索の追従']])+
 p('MSCガイドでは変形体同士のメッシュ粗密や剛性による推奨を示していますが、どの方式でも「細かい方を必ず従側」とする万能規則にはしません。使用方式・剛体面・二次要素の条件を合わせて選び、必要なら接触側の入替えへの感度を調べます。')],
 ['mesh','接触の探索と、メッシュの収束',
 p('探索距離を広げると、意図しない裏面や隣の部品を拾うことがあります。狭すぎると本来の接触を見つけません。法線方向、接触候補の組、初期間隙、厚さ、面の滑らかさを先に確認し、探索距離だけで問題を隠さないようにします。')+
 A.table(['確認する量','メッシュや設定を変えて見る理由'],[['合力・モーメント','荷重伝達の全体収支が保たれるか'],['接触域・開離境界','接触が始まる位置・範囲が安定するか'],['接触圧の分布','局所的な振動・節点の粗密の影響を見る'],['最大圧力・最大応力','角や点接触の特異性と有限値の収束を分ける'],['滑り量・散逸','摩擦則・接線剛性・増分幅への感度を見る']])+
 p('鋭い角、急な曲率変化、悪い要素形状は接触圧の不連続や収束困難を生みます。形状に存在する角を根拠なく丸めるのではなく、実物の曲率と評価したい量に合わせます。点や角の最大値だけが増え続けるなら、荷重経路の誤りなのか局所特異性なのかを切り分けます。')],
 ['hertz','材料が弾性でも、接触剛性は荷重で変わる',
 p("球を板にそっと置き、次に強く押します。接触跡が広がるので、荷重が倍でも最大圧力は単純に倍になりません。")+
 lab('hertz')+
 f('球と平面のHertz近似\n1/E*=(1−ν1²)/E1+(1−ν2²)/E2\na³=3PR/(4E*)、δ=a²/R\np(r)=p0√(1−r²/a²)、p0=3P/(2πa²)\nP=(4/3)E*√R δ^(3/2)\n接線剛性 dP/dδ=2E*a')+
 p('押すほど接触域が広がるため、一定の線形ばねでは全荷重範囲を再現できません。セカント剛性P/δと接線剛性dP/dδも異なります。この例では後者は前者の1.5倍です。微小な振動で使うのは、平衡点周りの接線剛性という考え方になります。')+
 p('Hertz近似は小さい接触域、滑らかな形状、摩擦なし、弾性体などの仮定があります。接触圧が大きく塑性化する、薄板が全体曲げする、表面粗さや接着が支配する場合は、そのまま理論値として使いません。合力の検算は∫₀ᵃ2πr p(r)dr=Pで行えます。')],
 ['glue','永久固着は、摩擦を大きくした接触ではない',
 p('永久固着は、指定された結合関係を保持して開離や相対滑りを許さない理想化です。摩擦接触は圧縮力がなくなると摩擦力も失うため、μを大きくしても引張を伝える接着層と同じにはなりません。')+
 p('また、永久固着を設定しただけでは接着剤の厚さ、有限の剛性、剥離強度、破壊エネルギーを表しません。これらが目的なら凝着要素や接着材料の構成則を検討します。異種要素を結ぶ場合は、並進だけでなく回転・曲げモーメントをどのように伝えるかも確認します。')+
 p('初期に相手を見つけられないと、意図した固着が形成されず剛体運動が残ることがあります。無応力で位置を寄せる操作は、形状や初期応力状態を変更します。許容距離と初期調整の記録を残します。'+ '<a href="elements.html#connector">結合・凝着要素</a>へ。')],
 ['gap','CGAP・PGAPで表せること、表せないこと',
 p('<a href="elements.html#gap">ストッパー・浮き上がり支持の実務例と力の検算</a>。'+card('CGAP')+'は定めた2点間の局所方向に、開閉・摩擦等の関係を置く要素です。面全体の相手を自動で探索する機能と同じではありません。接触点が面上を大きく移動する問題では、点の対応や向きが現象を追えるかを確認します。')+
 p('ドアの戸当たりなら、当たる場所と押し返す方向が決まっています。そこだけのすき間と力は一組の点で表せます。丸い先端が押し跡を広げる場合、同じ一点モデルから跡の幅や最大面圧は求まりません。知りたいのが合力か、面内の分布かで選びます。')+
 p('初期すき間と開閉時の剛性は'+card('PGAP')+'、点の位置と向きは'+card('CGAP')+'で確認できます。')],
 ['msc101','板の片端が浮くと、どこで支えるか',
 p('机に置いた剛な板の左右に小さな脚があります。板の中央に下向き100 Nだけを加えると、対称なら各脚が50 Nを受け持ちます。力を右脚の真上に移すと、右脚100 N、左脚0 Nです。左脚はこの瞬間、机に触れたままでもつじつまが合います。')+
 lab('feet')+
 p('さらに右脚より外側へ力を移すと、両脚を固定した計算は左脚に引張反力を要求します。接着していない脚にその力は出せません。他の支えがなければ板は右脚を支点に傾き始めます。材料が弾性のままでも、支えられる範囲が変わる例です。')],
 ['msc400','滑る距離が長いと、相手の面が入れ替わる',
 p('短い消しゴムを長い板へ押し付け、押す強さを保ったまま横へ動かします。最初に真下にあった板の点に印を付けると、消しゴムを長さ一本分ずらしたところで、その印は押し跡の外へ出ます。')+
 p('押し跡が同じ大きさでも、力を受ける相手は移ります。初めに向かい合った節点同士をずっと結ぶモデルでは、この移動を表せません。どれだけひずむかと、相手面上をどれだけ移動するかを別に考えます。')],
 ['siemens','横に動かして戻すと、力も同じ道を戻るか',
 p('粗い面に置いた部品を横ばねで引きます。一度も滑らない範囲で手を戻せば、ばねの伸びも元に戻ります。一度滑らせた後、手を止めて少し戻すと、まずばねの伸びが減ります。手を戻し始めた瞬間に部品も逆滑りするとは限りません。')+
 p('浮き上がりだけを知る場合、押し跡の移動を追う場合、一往復後の残りずれを知る場合では、残すべき仕組みが違います。<a href="theory.html#contact/friction">摩擦の往復図で試す</a> ／ <a href="analysis.html#contact-check">解析でMSC・Simcenterの適用範囲を確認する</a>。')],
 ['preload','締付けは、ボルトの引張と部材の圧縮を作る',legacy(4)+
 p('ナットを締めると、ボルトが伸び、頭部とナットの間の部材が圧縮されます。外部から開く荷重がなくても、ボルト軸力Fbと部材の圧縮力Fcが存在し、内部でつり合っています。これを締付け予荷重F0と呼びます。')+
 f('外力0：Fb=Fc=F0\nボルト伸び δb=F0/kb、部材短縮 δj=F0/kj\n必要な締付け短縮量 Δ=δb+δj=F0(1/kb+1/kj)\nF0=[kb kj/(kb+kj)]Δ')+
 p('kb=100 kN/mm、kj=400 kN/mm、F0=10 kNなら、ボルト伸び0.10 mm、部材短縮0.025 mm、締付け相対量0.125 mmです。見かけの小さい締付け変形でも、接触状態と外力後の荷重経路を変えます。')],
 ['stiffness','ボルト剛性と被締結体剛性を、何から見積もるか',
 p("同じ材質のボルトでも、細い軸部が長いほど同じ引張力でよく伸びます。各区間の伸びを足すと全体の伸びになります。")+
 f('段付きボルトの軸コンプライアンス：1/kb ≈ Σ Li/(Ei Ai)\n一様な部分なら kb=EA/L\n被締結体：kj=Fc/δj（指定した締付け領域・状態で評価）')+
 p('ねじ部、軸部、頭部・ナット付近では有効な変形範囲が違います。全長と呼び径だけで精密な剛性が決まるわけではありません。強度評価の有効断面積と、剛性の等価断面積も目的をそろえて選びます。')+
 p('被締結体の圧縮領域は、座面、板厚、穴、周囲の剛性、接触状態で変わります。圧縮円すい等の近似は幾何と適用範囲を確認して使います。有限要素で見積もる場合も、どの面の相対変位を測るかをそろえ、剛体変位や局所の座面食込みを無意識に混ぜないようにします。')],
 ['partition','外力の全てが、ボルト軸力の増加になるわけではない',
 p("締めた2枚の板を引き離します。加えた力はボルトの軸力を増やす分と、板の押し付けを弱める分とに分かれます。")+
 lab('bolt')+
 f('開離前：外側面の引張荷重F、共通の変位増分Δu\nΔFb=kb Δu、締付け減少 ΔFc=kj Δu\nF=ΔFb+ΔFc=(kb+kj)Δu\nC=kb/(kb+kj)\nFb=F0+C F、Fc=F0−(1−C)F\nFc=0となる外力：Fsep=F0/(1−C)')+
 p('図で剛性比を4にして、8 → 12.5 → 15 kNと引きます。8 kNではボルトが11.6 kNで引かれ、板はまだ3.6 kNで押し合います。12.5 kNで締付け力もすき間も0。15 kNでは板の間に0.025 mmのすき間ができ、ボルトが15 kNすべてを受けます。')+
 p('外側の面を軸に沿って引く例です。偏心して板が曲がると端だけ先に浮くので、この開離荷重をそのまま使えません。<a href="https://ntrs.nasa.gov/citations/20250005284" target="_blank" rel="noopener">NASAの締結部荷重分担の解説 ↗</a>')+
 p('開離後、この単純モデルではFb=F、Fc=0となります。開離前の式を延長してFcを負にすると、接合面が引張を伝えることになり、接触の仮定に反します。ボルトの繰返し軸力範囲が小さくなる利点も、開離を跨ぐと変わります。')],
 ['stages','締付け → 締付け変形の保持 → 外力',
 p("ナットを締め、工具を外し、その後で継手を引っ張ります。工具を外したときのボルトの伸びが次の工程の出発点です。")+
 lab('stages')+
 A.table(['工程','与えるもの','確認する結果'],[['1 締付け','目標軸力または締付け相対変形','ボルト軸力、部材の圧縮、接触範囲'],['2 保持','前工程で得た締付け相対量を保つ','外力なしで軸力・接触状態が不意に消えないか'],['3 外力','保持を継続してサービス荷重を加える','軸力増分、残存締付け、滑り、開離']])+
 p('<strong>保持するのは締付け用の相対量であり、軸力を一定に固定することではありません。</strong>外力を加えれば、ボルト自身の弾性伸びも軸力も変化します。実物でナットを締め終えた状態と、試験機が常に一定の力で引く状態を区別します。')+
 p('締付けと保持の指定は<a href="analysis.html#contact-check">解析の接触設定</a>、前段階からの追加変位は'+card('SPCR')+'で確認できます。')],
 ['bolt-cards','ボルトをどこで切って軸力を考えるか',
 p('軸力を知りたいときは、ボルトの軸部を輪切りにして片側を取り出すと考えます。切り口全体が引き合う力が軸力です。切断面上の一点だけの応力を読んでも、何kNで締まっているかは決まりません。')+
 p('一様な引張なら「軸方向の応力×断面積」で軸力が出ます。曲げも受ける場合は切り口の片側で引張が増え、反対側で減るので、各部の符号付きの力を足します。同じ断面の表裏は作用・反作用です。一方の面で一度だけ数えます。')],
 ['shear','横荷重は、摩擦から孔当たりへ経路が変わる',
 p("2枚の板を強く挟むと、小さい横荷重は面の摩擦で渡ります。締付けが失われると、同じ横荷重で滑ることがあります。")+
 lab('shear')+
 f('1面・一定μ・一方向の全体滑りの上限：Vlim=μ Fc\n開離前の簡易式を使えば Vlim=μ[F0−(1−C)F]\n外力Fで締付けが減ると、横荷重の摩擦余裕も減る')+
 p('摩擦で保持される段階では、ボルト軸のせん断が横荷重の全てを受けるとは限りません。滑った後には孔壁の支圧、ボルト軸のせん断・曲げなどへ荷重が移ります。最初から孔を剛体結合すると、クリアランスと滑り後の経路を消してしまう場合があります。')+
 p('すべり面が複数ある場合は、各面の法線力と相対運動を確認します。接触面の数を数えて単純にμF0を掛け合わせないようにします。偏心横荷重・こじり・接触圧の偏りは、この全体上限だけでは評価できません。')],
 ['torque','締付けトルクから、軸力を一意に決められるか',
 p("同じトルクで締めても、ねじや座面が乾いている場合と潤滑している場合では、得られる軸力が変わります。")+
 lab('torque')+
 f('概算式：T=K F0 d → F0=T/(K d)\nT=20 N·m=20,000 N·mm、d=10 mm\nK=0.20ならF0=10 kN\nK=0.12なら16.67 kN、K=0.30なら6.67 kN')+
 p('ねじ・座面だけを潤滑してKが小さくなると、同じトルクでも軸力は大きくなります。一方、板と板の合わせ面だけに油が入り、軸力が同じでμだけ下がれば横滑りしやすくなります。「油を差した」の一言で判断せず、どの面かを区別します。')+
 p('解析では平均軸力だけでなく、締付け方法・潤滑・ばらつきに基づく範囲を持たせます。大きい予荷重側ではボルト・座面の強度、小さい側では開離・滑り・密封性が厳しくなり得ます。規格や実験で必要な値を決め、ここでの仮のKを設計の推奨値には使いません。')],
 ['loss','温度差・なじみ・緩和で予荷重が変わる',
 p("締結後に塗膜が少しつぶれて重なった板が薄くなると、ナットを回していなくてもボルトの伸びが減り、締付け力が落ちます。")+
 lab('loss')+
 f('keq=kb kj/(kb+kj)\n部材とボルトの自由膨張差 ΔLth=(αj Lj−αb Lb)ΔT\n座面等のなじみ量sを正の短縮とすると\nΔF0≈keq(ΔLth−s)\n同じ長さL、αj>αbで昇温すると、この近似では軸力が増える')+
 p('温度でヤング率も変わる、各部の温度が違う、樹脂がクリープする、座面が塑性化する場合は、この一定剛性の式だけでは足りません。時間依存の緩和、永久的ななじみ、可逆的な熱膨張を分けて入力します。')+
 p('線形予測の軸力が0以下になったら、ボルトが同じ式で圧縮を受け続けると解釈せず、締付け喪失と接触状態を解き直します。回転を伴う緩みは別の機構で、軸力の低下だけでねじの戻り回転を再現したことにはなりません。')],
 ['modeling','簡易から詳細へ：評価したい量で選ぶ',legacy(5)+
 A.table(['モデルの水準','扱うもの','使える判断／残る限界'],[['軸ばね・片側接触','締付けと荷重分担の基本','軸力・開離の概算。こじり・ねじ谷の応力は求めない'],['梁ボルト＋座面・接触面','全体の変形、荷重分配、孔当たり','曲げ・横力を含む分担。座面や接続の理想化に依存'],['実体ボルト・板・接触','局所の圧力、板曲げ、部分開離','メッシュ・摩擦・予荷重の品質を検証する必要'],['ねじ山・局所詳細','ねじの荷重分担、局所応力・損傷','材料・形状・接触と非常に細かいメッシュが必要']])+
 p('板がてこのように変形して端で相手を押す「こじり」があると、その接触反力がボルトをさらに引っ張ります。単純な軸力分担だけでは増分を予測できません。板の曲げ、支持位置、座面、開離する縁を保ったモデルで確認します。')+
 p('<a href="analysis.html#contact/lift-off/results">解析：偏心荷重を受ける2本のボルトの負担を検算する</a>')+
 p('詳細化は節点数を増やすことだけではありません。簡易モデルと同じ外力・予荷重・拘束をそろえ、どの仮定を変えたために結果が変わったかを追います。学習用の操作図は一般力学の計算であり、配布用の実行済みNastranモデルではありません。')],
 ['convergence','同じ600 Nでも、押し跡は違う',
 p('板を平らな台に垂直に押し付けます。圧力が一様なら、300 mm²に2 MPaがかかる場合も、100 mm²に6 MPaがかかる場合も、台が受ける力は600 Nです。1 MPaは1 N/mm²なので、圧力に面積を掛けると力になります。')+
 p('前者は広く軽く、後者は狭く強く当たっています。台が荷重を支えるかを知るには合力、柔らかい表面に跡が付きそうかを知るには局所の圧力を見ます。')],
 ['diagnosis','押し跡の濃さが違うとき、力はどう足すか',
 p('左・中央・右に100 mm²ずつ印を付け、区画の平均面圧を調べます。平行な面で圧力から受ける力を比べます。')+
 A.table(['区画','平均面圧','受け持つ力'],[['左','0 MPa','0 N'],['中央','2 MPa','200 N'],['右','4 MPa','400 N']])+
 lab('footprint')+
 p('合計は600 Nです。最大の4 MPaを面全体300 mm²に掛けてしまうと1,200 Nになり、右側の濃い跡を全面に引き延ばしたことになります。左の圧力が0の理由は、すき間を見て確かめます。')],
 ['checks','同じ合力でも、傾ける作用は変わる',
 p('3区画の中心を左から0、10、20 mmとします。各区画の力がその中心に作用すると、左端まわりのモーメントは200×10＋400×20＝10,000 N·mm。合力600 Nの作用位置は10,000÷600≒16.7 mmです。押し跡の幾何学的な中央10 mmより右へ寄ります。')+
 p('台が板を押す600 Nと、板が台を押す600 Nは同じ接触の両側です。板だけを取り出してつり合いを見るなら、板に作用する側を数えます。実際の出力の面・符号・平均化は<a href="analysis.html#contact-check">解析の接触状態の確認</a>へ。')]
 ];
 const questions=[
 ['すき間0.4 mm、k=1000 N/mm。下向き700 Nなら台の反力は？','接触しu=0.4 mm。ばねが400 N、台が300 Nを受け、合計700 Nです。'],
 ['厚さ4 mmの平行シェル2枚。中立面の距離3 mmはすき間3 mm？','表面のすき間は3−(4+4)/2=−1 mmで、1 mmの干渉です。'],
 ['N=1000 N、μ=0.3。固着中に横100 Nなら摩擦力は300 N？','必要な100 Nです。300 Nは上限で、常に作用する力ではありません。'],
 ['全体T=200 N、μN=300 Nなら面全体が固着している？','限りません。低圧の部分だけが上限へ達し、部分滑りしている場合があります。'],
 ['Hertzの球接触で荷重8倍。接触半径・接近量・最大圧力は？','aはPの1/3乗なので2倍、δはPの2/3乗なので4倍、p0はPの1/3乗なので2倍です。'],
 ['永久固着を、非常に大きい摩擦係数だけで置き換えられる？','摩擦接触は開離時に法線力も摩擦力も0です。引張も伝え開離しない永久固着とは違います。'],
 ['右脚の真上に荷重を移し、左脚の反力がゼロになった。すき間もできた？','それだけでは決まりません。左脚は無荷重で触れた状態でもつり合えます。開いたかはすき間で判別します。'],
 ['押し跡の面積が同じなら、滑らせても同じ相手節点を結んでよい？','板の上を大きく移動すると、跡の中に入る板の点が入れ替わります。固定した節点対ではこの動きを表せません。'],
 ['F0=10 kN、kb=100、kj=400 kN/mm。外力8 kNでFbとFcは？','C=0.2、Fb=10+0.2×8=11.6 kN、Fc=10−0.8×8=3.6 kN。Fb−Fc=8 kNです。'],
 ['同じ締結の開離外力と、締付け短縮量は？','Fsep=10/(1−0.2)=12.5 kN。締付け短縮量は10/100+10/400=0.125 mmです。'],
 ['同じ締結で外力8 kN、μ=0.3。1面の全体滑り上限は？','残存締付け3.6 kNなので1.08 kNです。初期10 kNを使った3 kNではありません。'],
 ['K=0.2、d=10 mm、20 N·mの締付け軸力は？','20,000/(0.2×10)=10,000 N=10 kN。Kのばらつきで軸力も変わります。'],
 ['締めた後で板を引くと、ボルト軸力は締付け時の10 kNのまま？','通常の締結ではナットの締込み位置を保ちます。外力でさらにボルトが伸びれば軸力も増えます。'],
 ['面積300 mm²、最大面圧4 MPa。合力は1,200 Nでよい？','全面が一様に4 MPaなら成立します。分布が違うときは各区画の平均面圧にその面積を掛けて足します。']
 ];
 sections.push(['questions','自分で確かめる','<div class="theory-quiz">'+questions.map(([q,a],i)=>`<details><summary>${i+1}. ${q}</summary><p>${a}</p></details>`).join('')+'</div>']);
 sections.push(['sources','参照範囲と関連教材',
 p('解説と新しい模式図・操作図は一般力学に基づく独自構成です。公式の図・入力ファイル・出力値は転載していません。操作図は独立した理論計算であり、実行済みNastranモデルではありません。')+
 A.table(['資料','確認範囲'],[['MSC Nastran 2025.1 線形静解析ガイド','第17章 PDF603–630：片側支持、SOL 101接触、永久固着、探索・制限・Smart Defaults'],['MSC Nastran 2025.1 QRG','BOLT 1331–1332、BOLT1 1333–1335、SPCR 2893–2894、CGAP 1418以降、PGAP 2616以降、BCONTACT・接触制御'],['NASA TM-106943, J. A. Chambers (1995)','締付け軸力、ばねによる荷重分担、荷重導入面、予荷重の変動'],['A. F. Bower, Applied Mechanics of Solids §5.4.10','摩擦なし球接触の弾性理論'],['保管中のATA Engineering Simcenter講習資料','SOL 401/402の方式と制御カードの区別。現行版の既定値照合とは区別']])+
 p(source(stat+'#page=603','MSC：接触の章')+' · '+source(qrg+'#page=1331','QRG：BOLT / BOLT1')+' · '+source(qrg+'#page=2893','QRG：SPCR')+' · '+source(qrg+'#page=2616','QRG：PGAP'))+
 p(source('https://ntrs.nasa.gov/api/citations/19960012183/downloads/19960012183.pdf','NASA：予荷重締結の基礎')+' · '+source('https://solidmechanics.org/text/Chapter5_4/Chapter5_4.htm','Bower：弾性接触'))]);
 function html(){return '<div class="analysis-head"><span class="analysis-sol">接触・摩擦・締結</span><h1>接触・摩擦・締結の理論</h1><p>開閉・滑り・締付けを、許す運動と伝わる力から読み解きます。</p></div>'+A.intro({goals:['接触と支持・固着を区別し、開閉と滑りを判断する','締付けから保持・外力までの荷重経路を式と図で追う','接触圧・軸力・収支・感度で設定の誤りを見分ける'],prerequisites:[['theory.html#boundary','境界条件と拘束'],['theory.html#common-loads','荷重の理論'],['theory.html#materials','材料理論']],points:['接触する範囲と滑る範囲も未知量になる。','締付け変形の保持と、軸力を一定にする制御は違う。','共通の力学と、製品・SOLごとの実装条件を分けて確認する。']})+A.toc(sections.map(([id,t])=>['contact-'+id,t]))+sections.map(([id,t,b],i)=>A.section(`${i+1}. ${t}`,b,'contact-'+id)).join('');}
 const labels={'接触して押し合う':'g = 0','すき間が開く':'g > 0','接触圧あり':'pn > 0','接触圧 0':'pn = 0','開く':'g > 0','閉じる':'g = 0','圧縮だけ伝える':'pn ≥ 0','離れると力ゼロ':'pn = 0','接触面':'A','摩擦力':'T','法線力':'N'};
 function connect(root){for(const e of root.querySelectorAll('[data-contact-legacy]')){e.innerHTML=window.TheoryTopicVisuals.contact[+e.dataset.contactLegacy];for(const t of e.querySelectorAll('svg text'))if(labels[t.textContent]!==undefined)t.textContent=labels[t.textContent];}window.ContactLabs.connect(root);A.bindNavigation(root);}
 const aliases={overview:'meaning',friction:'friction',surfaces:'surface',products:'msc101',bolts:'preload',management:'torque',verification:'convergence'};
 function focusSection(key){const t=document.getElementById('contact-'+(aliases[key]||key));if(t)requestAnimationFrame(()=>t.scrollIntoView({block:'start'}));}
 function mount(root){root.innerHTML=html();connect(root);}
 window.ContactChapter={sections,questions,html,connect,mount,focusSection};
})();
